<script setup lang="ts">import {ref,reactive,onMounted} from 'vue';import {specs} from '../stores/specs';import {canWrite} from '../stores/auth';import {useTask} from '../hooks/useTask';import {modeLabels} from '../constants/enums';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';const name=ref(''),p=reactive({mode:'fit',n_bins:8,min_pairs:5,max_distance:200,nugget:.2,fixed_sill:8,fixed_range:55,sill_min:.1,sill_max:50,range_min:5,range_max:300,condition_limit:1e10,negative_tolerance:1e-10});const {error,busy,act}=useTask();onMounted(specs.load);function submit(){act(async()=>{await specs.create({name:name.value,...p});name.value=''})}</script><template><PageHeading index="02 / 变异函数" title="把基台、距离尺度与边界，先写清。" note="指数协方差C(h)=sill·exp(−h/range)+nugget·I(h=0)。部分基台sill不含nugget；γ(0)=0，非零距离含nugget。"/><div class="two-col"><section><article v-for="r in specs.items.value" :key="r.id" class="spec-row"><p class="eyebrow">VARIOGRAM SPECIFICATION</p><h2>{{r.name}}</h2><p>{{modeLabels[r.mode]}} · 固定nugget {{r.nugget}} pp²</p><dl><div><dt>距离箱</dt><dd>{{r.n_bins}}</dd></div><div><dt>最大lag</dt><dd>{{r.max_distance}}m</dd></div><div><dt>最小对数/箱</dt><dd>{{r.min_pairs}}</dd></div></dl><p v-if="r.mode==='fit'">sill界限[{{r.sill_min}},{{r.sill_max}}]，range界限[{{r.range_min}},{{r.range_max}}]米；触界提示。</p><p v-else>固定sill={{r.fixed_sill}}，range={{r.fixed_range}}米，不从本批拟合。</p></article></section><form v-if="canWrite()" class="editor-panel" @submit.prevent="submit"><h2>建立模型口径</h2><label>口径名称<input v-model="name" required minlength="2"></label><label>参数来源<select v-model="p.mode"><option value="fit">经验箱计数加权拟合</option><option value="fixed">外部固定参数</option></select></label><label>固定nugget / pp²<input type="number" v-model.number="p.nugget" min="0" max="1000" step="any"></label><div class="form-pair"><label>距离箱数<input type="number" v-model.number="p.n_bins" min="3" max="20"></label><label>最小对数/箱<input type="number" v-model.number="p.min_pairs" min="1" max="100"></label></div><label>最大lag / 米<input type="number" v-model.number="p.max_distance" min=".001" max="20000" step="any"></label><template v-if="p.mode==='fit'"><div class="form-pair"><label>sill下界<input type="number" v-model.number="p.sill_min" min=".000001" step="any"></label><label>sill上界<input type="number" v-model.number="p.sill_max" min=".000001" step="any"></label></div><div class="form-pair"><label>range下界/米<input type="number" v-model.number="p.range_min" min=".000001" step="any"></label><label>range上界/米<input type="number" v-model.number="p.range_max" min=".000001" step="any"></label></div></template><template v-else><label>固定部分基台sill<input type="number" v-model.number="p.fixed_sill" min=".000001" step="any"></label><label>固定range/米<input type="number" v-model.number="p.fixed_range" min=".000001" step="any"></label></template><label>系统条件数上限<input type="number" v-model.number="p.condition_limit" min="1000" max="1000000000000" step="any"></label><p class="method-note">微负方差阈值={{p.negative_tolerance}}×max(1,C0)，仅数值微负截0，严重负值失败。</p><Notice :message="error"/><button :disabled="busy">保存变异函数口径</button></form></div></template>
